<script setup>
import LocalizedStatusBadge from '@/shared/presentation/components/LocalizedStatusBadge.vue'
import ContextPageHeading from '@/shared/presentation/components/ContextPageHeading.vue'
import { computed, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useAuthStore } from '@/boundedcontext/identityaccess/application/stores/auth.store'
import { useSafeLabDemoStore } from '@/shared/application/stores/demo.store'
const router = useRouter(); const auth = useAuthStore(); const demo = useSafeLabDemoStore(); auth.restoreSession()
const search = ref(''); const status = ref('all'); const severity = ref('all')
const user = computed(() => auth.currentUser)
const incidents = computed(() => demo.scopedItems('incidents', user.value).filter((incident) => {
  const text = `${incident.code} ${incident.title} ${incident.description} ${incident.assignedTo}`.toLowerCase()
  return text.includes(search.value.toLowerCase()) && (status.value === 'all' || incident.status === status.value) && (severity.value === 'all' || incident.severity === severity.value)
}))
const summary = computed(() => ({ total: incidents.value.length, open: incidents.value.filter(i=>i.status==='open').length, investigating: incidents.value.filter(i=>i.status==='investigating').length, critical: incidents.value.filter(i=>i.severity==='critical').length }))
</script>
<template>
  <section class="page">
    <div class="page-hero compact"><ContextPageHeading :description="$t('legacy.label_24d634bcd7')" /></div>
    <div class="records-quick-actions"><RouterLink class="btn records-view-button" to="/alertsincidents/records/incidents"><i class="pi pi-list"></i> {{ $t('records.viewAll') }}</RouterLink></div>
<div class="page-toolbar"><button v-if="auth.hasPermission('alerts.acknowledge')" class="btn warning" @click="demo.escalateAlert(demo.alerts.find(a=>a.status!=='resolved')?.id)">{{ $t('legacy.label_da5d071a4d') }}</button></div>
    <div class="kpi-grid"><article class="kpi-card"><span class="kpi-icon"><i class="pi pi-list"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_294dc2cc4a') }}</span><strong>{{ summary.total }}</strong><small>{{ $t('legacy.label_a87484c771') }}</small></div></article><article class="kpi-card warning"><span class="kpi-icon"><i class="pi pi-clock"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_cf9b77061f') }}</span><strong>{{ summary.open }}</strong><small>{{ $t('legacy.label_988ab08886') }}</small></div></article><article class="kpi-card"><span class="kpi-icon"><i class="pi pi-search"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_ce0ee52356') }}</span><strong>{{ summary.investigating }}</strong><small>{{ $t('legacy.label_7e3e171a15') }}</small></div></article><article class="kpi-card danger"><span class="kpi-icon"><i class="pi pi-exclamation-triangle"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_04b7b26c8c') }}</span><strong>{{ summary.critical }}</strong><small>{{ $t('legacy.label_40cd1b46f9') }}</small></div></article></div>
    <div class="filter-bar"><div class="field"><label>{{ $t('legacy.label_bce0641417') }}</label><input v-model="search" class="input" :placeholder="$t('uiReview.incidentSearchHint')"></div><div class="field"><label>{{ $t('legacy.label_bae7d5be70') }}</label><select v-model="status" class="select"><option value="all">{{ $t('legacy.label_6a72085653') }}</option><option value="open">{{ $t('legacy.label_cf9b77061f') }}</option><option value="investigating">{{ $t('legacy.label_ce0ee52356') }}</option><option value="resolved">{{ $t('legacy.label_d999aeb054') }}</option><option value="closed">{{ $t('legacy.label_88d86b7721') }}</option></select></div><div class="field"><label>{{ $t('legacy.label_de314fa0c9') }}</label><select v-model="severity" class="select"><option value="all">{{ $t('legacy.label_6a72085653') }}</option><option value="critical">{{ $t('legacy.label_04b7b26c8c') }}</option><option value="warning">{{ $t('legacy.label_e9c4556335') }}</option><option value="info">{{ $t('legacy.label_4b631f6984') }}</option></select></div></div>
    <div class="incident-grid"><article v-for="incident in incidents" :key="incident.id" :class="['incident-card', incident.severity]"><div class="card-header"><div><p class="eyebrow">{{ incident.code }} · {{ $t(`platformUi.state_${incident.severity}`) }}</p><h3>{{ incident.title }}</h3><p>{{ incident.description }}</p></div><LocalizedStatusBadge :status="incident.status" context="incidents"/></div><div class="pair-grid"><div class="pair-box"><span>{{ $t('legacy.label_bb2279f04d') }}</span><strong>{{ incident.assignedTo }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_4c1aeebc43') }}</span><strong>{{ incident.dueDate }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_7ea014de7b') }}</span><strong>{{ incident.evidence }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_9101fc1744') }}</span><strong>{{ incident.relatedSensorId }}</strong></div></div><div class="actions"><button class="btn small primary" @click="router.push(`/alertsincidents/incident-detail/${incident.id}`)">{{ $t('legacy.label_badd385121') }}</button><button v-if="auth.hasPermission('incidents.resolve')" class="btn small success" @click="demo.updateIncidentStatus(incident.id,'resolved')">{{ $t('legacy.label_ac7f958cc0') }}</button></div></article></div>
  </section>
</template>
